 1	method BinarySearch(a: array<int>, key: int) returns (n: int)
 2	  requires forall i,j :: 0<=i<j<a.Length ==> a[i]<=a[j]
 3	  ensures 0<= n <=a.Length
 4	  ensures forall i :: 0<= i < n ==> a[i] < key
 5	  ensures n == a.Length ==> forall i :: 0 <= i < a.Length ==> a[i] < key
 6	  ensures forall i :: n<= i < a.Length ==> a[i]>=key
 7	{
 8	  var lo, hi := 0, a.Length;
 9	  while lo<hi
10	    invariant 0<= lo <= hi <= a.Length
11	    invariant forall i :: 0<=i<lo ==> a[i] < key
12	  {
13	    var mid := (lo + hi) / 2;
14	    if a[mid] < key {
15	      lo := mid + 1;
16	    } else {
17	      hi := mid;
18	    }
19	  }
20	  n:=lo;
21	}

